import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import './styles.css';

const total = 8;

function Progress() {
  const [done, setDone] = createSignal(1);
  const percent = () => Math.round((done() / total) * 100);

  return (
    <>
      <p>
        {done()} of {total} tasks done{' '}
        <button onClick={() => setDone((n) => Math.min(total, n + 1))}>+</button>
        <button onClick={() => setDone((n) => Math.max(0, n - 1))}>−</button>
      </p>
      <div class="track">
        <div class="bar" style={{ width: '0%' }} />
      </div>
    </>
  );
}

render(() => <Progress />, document.getElementById('app'));

.track {
  width: 300px;
  height: 20px;
  background: #eee;
  border-radius: 10px;
  overflow: hidden;
}

.bar {
  height: 100%;
  background: #446b9e;
  transition: width 0.3s;
}

.bar.low {
  background: #c0392b;
}

.bar.done {
  background: #27ae60;
}

import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import './styles.css';

const total = 8;

function Progress() {
  const [done, setDone] = createSignal(1);
  const percent = () => Math.round((done() / total) * 100);

