        <button onClick={() => setDone((n) => Math.max(0, n - 1))}>−</button>
      </p>
      <div class="track">
        <div
          class={['bar', { low: percent() < 30, done: percent() === 100 }]}
          style={{ width: `${percent()}%` }}
        />
      </div>
    </>
  );
}

render(() => <Progress />, document.getElementById('app'));

.track {
  width: 300px;
  height: 20px;
  background: #eee;
